INSERT INTO public.flashcards
  (id, deck_id, card_type, front, back, tags, is_official, user_id, created_at)
VALUES
  ('25f6f207-e219-5ee0-b00a-3ba643d74263', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la diferencia fundamental entre psicosis y neurosis?', 'La prueba de realidad. En psicosis hay PÉRDIDA del contacto con la realidad (alucinaciones, delirios). En neurosis se mantiene (ansiedad, depresión, obsesiones).', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('2d8f7c45-0af9-5484-aa04-9593b829b1a6', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cómo se distinguen psicosis breve, esquizofreniforme y esquizofrenia?', 'Solo por duración. Psicótico breve: ≥1 día pero <1 mes, con retorno al estado previo. Esquizofreniforme: ≥1 mes, <6 meses. Esquizofrenia: ≥6 meses. La clínica es la misma.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('fd2ff478-a072-5570-b48e-f8c4dc7e5e52', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la diferencia clave entre esquizoafectivo y trastorno del ánimo con psicosis?', 'En esquizoafectivo debe haber ≥2 SEMANAS de delirios o alucinaciones SIN síntomas afectivos mayores a lo largo de la enfermedad. Si la psicosis aparece SOLO dentro del episodio afectivo, es trastorno bipolar/depresivo con psicosis, no esquizoafectivo.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('cf227268-bd1b-518e-9ef1-d98c04e79c5f', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuáles son los 2 subtipos del trastorno esquizoafectivo?', 'Tipo bipolar (con episodios maníacos, con o sin depresión mayor) y tipo depresivo (solo con episodios depresivos mayores). El bipolar tiene mejor pronóstico.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('b042214c-4c00-5655-9757-47204cfb50bb', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué porcentaje del trastorno esquizofreniforme progresa a esquizofrenia?', 'Aproximadamente dos tercios (~⅔). El pronóstico mejora con las características favorables: inicio rápido de síntomas prominentes, confusión/perplejidad, buen funcionamiento previo, ausencia de aplanamiento afectivo.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('90060110-4ae8-5fa4-85a0-137126365330', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuántos síntomas se requieren para un episodio maníaco y durante cuánto tiempo?', '≥3 de 7 síntomas (≥4 si el ánimo es solo irritable) durante ≥1 semana. O cualquier duración si requiere hospitalización o hay psicosis.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('aa4b52d7-a4a2-50aa-987d-bba2dca438f2', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué diferencia la hipomanía de la manía?', 'Hipomanía: ≥4 días, sin deterioro marcado, sin psicosis, no requiere hospitalización. Manía: ≥1 semana, con deterioro o psicosis. Si hay psicosis, por definición es manía.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('240912e3-1dae-51fb-aa8e-5db3f27ab651', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la forma más grave de bipolaridad?', 'Bipolar tipo I. Requiere solo un episodio maníaco (la depresión no es necesaria, aunque es frecuente).', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('2c9ccde4-c6c2-5621-8e83-719cc5d60863', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es el tratamiento de elección para la depresión bipolar?', 'Lamotrigina (prevención), litio, quetiapina. Los antidepresivos solo se usan con estabilizador de base por riesgo de viraje maníaco.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('a69df2bf-51c7-5cc7-98ba-e533f5469d1a', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuántos síntomas se requieren para el diagnóstico de depresión mayor y durante cuánto tiempo?', '≥5 de 10 síntomas durante ≥2 semanas, casi todos los días. Al menos uno debe ser ánimo deprimido o anhedonia.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('0f1aa751-17f7-531b-9e4b-ba40a9615078', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuáles son los 5 tipos de trastorno delirante?', 'Persecutorio (el más común · puede ser hostil), erotomaníaco, grandeza, celotípico (puede ser hostil) y somático.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('9990a42d-a10d-510b-b887-52dea94c8a49', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué diferencia el delirante somático de la hipocondría?', 'En el trastorno delirante somático, el delirio NO desaparece con pruebas médicas normales (la convicción es fija). En la hipocondría/IAD, la preocupación persiste pero puede haber dudas.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('485bba8f-5ac1-5d61-9083-14e1ad74ffa3', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué tipo de esquizofrenia tiene peor pronóstico?', 'La desorganizada (hebefrénica): comienzo precoz y grave, afecta las emociones.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('0a2421e3-1cee-54b8-84e3-f24aad1def57', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué subtipo de esquizofrenia es el más frecuente?', 'El paranoide: predominan los síntomas positivos, afecta el pensamiento, pronóstico favorable.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('503e21a6-78e6-585d-a822-b50cab334c4e', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', 'Menciona las 4 vías dopaminérgicas y qué pasa si fallan.', 'Mesolímbica → síntomas positivos de esquizofrenia. Mesocortical → síntomas negativos. Nigroestriada → Parkinson/extrapiramidalismo. Tuberoinfundibular → hiperprolactinemia.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('34b36c27-ff38-56d9-914c-305fbd46a73a', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuáles son los síntomas positivos y negativos de la esquizofrenia?', 'Positivos: alucinaciones, delirios, pensamiento desorganizado. Negativos: aplanamiento afectivo, abulia, anhedonia, alogia (↓ habla), aislamiento social.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('a5a6d22f-f1c2-55dd-9394-5d061f36f2a0', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la duración mínima para diagnosticar esquizofrenia?', '≥1 mes de síntomas activos del criterio A (al menos uno debe ser delirio, alucinación o discurso desorganizado) + signos continuos del trastorno durante ≥6 meses.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('db5689b8-b88e-5bb0-8ef9-282ad1b18a9c', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es el único antipsicótico eficaz en esquizofrenia refractaria y qué riesgo tiene?', 'Clozapina. Riesgo de agranulocitosis fatal. Requiere hemograma semanal los primeros 6 meses, luego mensual.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('cd10971a-11e9-54e2-8a35-85ea49d29f91', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuáles son los factores de riesgo de suicidio en esquizofrenia?', 'Sexo masculino, menor de 30 años, desempleo, depresión previa, antecedentes de abuso de sustancias, internación reciente.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('c9ab47be-a7f6-5aa4-b923-cd996a4febc3', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué precipitantes pueden causar recaídas en bipolaridad?', 'Mala adherencia al tratamiento, alteraciones del sueño (dormir mucho o poco), drogas y automedicación (café, THC, alcohol), mala medicación por diagnóstico incorrecto.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('14ddd99d-b7f1-5337-b002-895363eea93d', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la duración EXACTA para diferenciar trastorno psicótico breve, esquizofreniforme y esquizofrenia?', 'Psicótico breve: ≥1 día pero <1 mes · Esquizofreniforme: ≥1 mes pero <6 meses · Esquizofrenia: ≥6 meses. La única diferencia es el tiempo.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('795e0ca0-149a-560e-90a9-e6f5ffc90a81', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué regla define esquizoafectivo vs esquizofrenia con síntomas afectivos?', 'En esquizoafectivo debe haber ≥2 semanas de delirios o alucinaciones SIN síntomas afectivos mayores durante el curso de la enfermedad. Si siempre coexisten, es un trastorno del ánimo con síntomas psicóticos, no esquizoafectivo.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('1f269a5b-0706-5ea2-a7c7-fd4975a55a21', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuáles son las 4 vías dopaminérgicas y qué pasa si cada una falla?', 'Mesolímbica: hiperactiva → síntomas positivos. Mesocortical: hipoactiva → síntomas negativos/cognitivos. Nigroestriada: bloqueada → extrapiramidalismo. Tuberoinfundibular: bloqueada → hiperprolactinemia.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('a548a49d-15f8-56fe-a557-03f0966fd977', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', 'Paciente con esquizofrenia presenta rigidez muscular severa, hiperpirexia, diaforesis y CPK elevada tras iniciar haloperidol. ¿Dx y manejo?', 'Síndrome neuroléptico maligno (SNM). Urgencia. Suspender el antipsicótico, enfriamiento, hidratación, dantroleno o bromocriptina. Mortalidad hasta 10% si no se trata.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('77163c10-e228-5bfd-a160-26968af24211', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la única indicación DEFINITIVA de clozapina?', 'Esquizofrenia resistente (falla a ≥2 antipsicóticos) y riesgo suicida alto. Requiere monitoreo hematológico por riesgo de agranulocitosis.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('2cbfa654-00f1-5a71-a2b5-b02931dd25e5', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Qué diferencia el delirio ''bizarro'' del no bizarro y por qué importa?', 'Delirio bizarro: contenido imposible físicamente (ej: ''me implantaron un chip que lee mis pensamientos''). No bizarro: posible aunque falso (ej: ''mi esposa me es infiel''). Delirante no bizarro → favorece trastorno delirante; bizarro → favorece esquizofrenia.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('3c7a9c2c-0539-5e44-9f43-0fc4f9e76789', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', 'Mujer de 45 años convencida de que su vecino está enamorado de ella, sin evidencia, hace 4 meses. Funciona bien en el trabajo, sin alucinaciones. ¿Dx?', 'Trastorno delirante tipo erotomaníaco. Criterios: delirios ≥1 mes, personalidad preservada, funciona bien. No cumple esquizofrenia (no hay deterioro ni síntomas negativos).', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('e359fbee-dffd-5b8e-981c-925784825890', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿En qué paciente con bipolar hay que tener MÁS cuidado con antidepresivos?', 'Bipolar I sin cobertura estabilizadora → riesgo de viraje maníaco. En bipolar II también, pero el riesgo es menor. NUNCA antidepresivo solo en bipolaridad — siempre con estabilizador del ánimo.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('d5d1dad2-f8df-51af-82db-f3fba9c40398', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuánto tiempo tarda el litio en mostrar efecto en manía aguda y qué nivel terapéutico se busca?', 'Inicio de efecto: 6-8 semanas para respuesta sostenida. Nivel terapéutico: 0.6-1.2 mEq/L. Por encima de 1.5 hay riesgo de toxicidad. Monitoreo por función renal y tiroidea.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('b4fa4b31-0136-5cb7-9203-664f440170f9', 'f2760c5b-a34f-5701-b8fe-d19e76cb7e85', 'basic', '¿Cuál es la diferencia entre manía e hipomanía en duración y severidad?', 'Manía: ≥1 semana + deterioro marcado o psicosis o hospitalización. Hipomanía: ≥4 días + cambio observable pero SIN deterioro marcado ni psicosis. Si hay psicosis, POR DEFINICIÓN es manía.', ARRAY['psicosis', 'salud_mental'], TRUE, NULL, now()),
  ('dabf6f4f-883a-5c65-9930-4fd88474dc09', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuándo la ansiedad se convierte en trastorno?', 'Cuando es excesiva, sin causa real proporcional, persiste en el tiempo (generalmente ≥ 6 meses) e interfiere con el funcionamiento diario.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('46fa70a4-80bd-5723-81ca-ee59e52d38f7', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuál es la diferencia entre un ataque de pánico y el trastorno de pánico?', 'El ataque de pánico es un episodio aislado (puede ocurrir en cualquier trastorno). El trastorno de pánico requiere ataques recurrentes inesperados con ≥ 1 mes de consecuencias psicológicas o conductuales.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('6196c427-2073-551f-9f8c-3a7507f460ad', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Qué es el mutismo selectivo y cómo se diferencia de la timidez?', 'Es la incapacidad de hablar en situaciones sociales específicas pese a poder hacerlo en otros contextos. La timidez es normal y no impide la comunicación; el mutismo selectivo sí lo hace de forma persistente (≥ 1 mes).', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('9b563880-4503-5919-984a-ef3942f50533', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuántos síntomas del ataque de pánico se requieren para diagnosticarlo?', 'Al menos 4 de los 13 síntomas descritos en el DSM-5, de inicio abrupto y que alcanzan la máxima intensidad en minutos.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('f7493f52-5964-5219-b233-a3e48f95bd35', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Por qué los pacientes con trastorno de pánico suelen consultar primero a cardiólogos, neumólogos y neurólogos?', 'Porque los síntomas físicos (palpitaciones, disnea, dolor precordial, parestesias) son prominentes y simulan enfermedades orgánicas antes de que se identifique el origen ansioso.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('29e056e4-7421-56f8-b727-2fcbd4056fd8', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuál es el rol del locus coeruleus en el trastorno de pánico?', 'Es el centro de alarma del tronco encefálico, regulador de noradrenalina. En el trastorno de pánico está hipersensible, lo que facilita la activación del sistema de alerta ante estímulos mínimos.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('7a8b5d2c-9ad1-584f-b200-7cb0ed07bdb6', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Qué es la teoría de la ''falsa sofocación'' en el trastorno de pánico?', 'Una hipersensibilidad al CO₂: el cerebro interpreta erróneamente señales de asfixia → desencadena hiperventilación y pánico incluso sin peligro real.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('a6128df5-fbf0-56af-99cb-7549212915a2', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuántos síntomas se requieren para el diagnóstico del TAG y durante cuánto tiempo?', 'Al menos 3 de 6 síntomas (en adultos; 1 en niños) presentes la mayoría de los días por ≥ 6 meses.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('7bf2e2f1-cfdf-5098-b572-6144043ecb61', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuáles son los ISRS de primera línea para los trastornos de ansiedad?', 'Fluoxetina, paroxetina y sertralina. Para el TAG se prefiere paroxetina o escitalopram.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('c99ff756-fce8-5192-a6f8-564b3999dc2f', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Qué diferencia a la fobia específica de la fobia social?', 'En la fobia específica el miedo se dirige a un objeto/situación concreta (animales, alturas). En la fobia social el miedo es al escrutinio y evaluación negativa por parte de otros en situaciones sociales.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('eee5e840-adc9-52b2-b34e-389e7a84cc95', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Por qué se desaconseja el consumo de cafeína en el trastorno de pánico?', 'La cafeína es un estimulante del SNC que puede desencadenar o intensificar ataques de pánico al activar el sistema adrenérgico.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('bb25a7e9-0873-5162-aa23-9ea42ebefcbb', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Qué comorbilidades son más frecuentes en el trastorno de ansiedad generalizada?', 'Depresión mayor y trastorno por uso de sustancias.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('7763fbde-1fa0-54ec-b103-68e21aeafd5e', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuál es la duración mínima recomendada del tratamiento farmacológico en el trastorno de pánico?', 'Mínimo 1 año tras la remisión de los síntomas, para evitar recaídas.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('01840208-b695-53bf-b311-d578c9614ceb', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Qué diferencia al TAG del trastorno de pánico?', 'En el TAG la ansiedad es crónica, difusa y sobre múltiples temas. En el TP hay episodios agudos e inesperados de terror máximo con síntomas físicos intensos.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('ae8fbc96-37a6-53b4-8464-ca0a04ae3be8', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuántas situaciones de los 5 grupos deben temerse para diagnosticar agorafobia?', 'Al menos 2 de las 5 situaciones (transporte público, espacios abiertos, lugares cerrados, multitudes, salir solo de casa).', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('81549657-e907-542b-b4df-8de1af04e870', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuál es la duración mínima para diagnosticar TAG?', '≥6 meses de preocupación excesiva sobre múltiples áreas, difícil de controlar, con ≥3 síntomas físicos (en niños basta 1).', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('78b15d5b-36d7-5284-a9e7-4a864101ae78', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', 'Varón de 28 años con episodios recurrentes de palpitaciones, disnea, miedo a morir, que duran 10 min. ¿Dx y manejo agudo vs mantenimiento?', 'Trastorno de pánico. Agudo: BZD de vida corta (alprazolam) y técnicas de respiración. Mantenimiento: ISRS (sertralina, paroxetina) + TCC — NUNCA BZD como mantenimiento.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('1b62b786-6ab3-5714-8133-9dbbdc4253e6', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Qué diferencia la agorafobia del trastorno de pánico?', 'Pánico: ataques recurrentes inesperados. Agorafobia: miedo a ≥2 situaciones (transporte, espacios abiertos/cerrados, multitud, fuera de casa solo) por temor a no poder escapar o recibir ayuda. Pueden coexistir.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('4acbebef-8ca7-5b4e-b9cc-0e11efc646f5', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Por qué no se usan BZD como tratamiento de mantenimiento en ansiedad?', 'Riesgo de dependencia, tolerancia, deterioro cognitivo, síndrome de abstinencia. Solo para crisis agudas o como puente (≤4 semanas) mientras el ISRS hace efecto.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('a5943826-be44-5c49-ae19-4887f065acb1', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', 'Niño de 6 años que se niega a ir a la escuela por miedo de que le pase algo a su mamá. Ansiedad marcada al separarse. ¿Dx?', 'Trastorno de ansiedad por separación. ≥4 semanas en niños, ≥6 meses en adultos. Dx diferencial con fobia escolar (miedo a la escuela en sí) y mutismo selectivo.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now())
INSERT INTO public.flashcards
  (id, deck_id, card_type, front, back, tags, is_official, user_id, created_at)
VALUES
  ('f81a1e3d-5ca3-5870-8b45-0c14a1b50a2a', 'f46157d1-56d5-5132-b1ab-e8bc594f129e', 'basic', '¿Cuál es la dosis efectiva de sertralina en ansiedad vs depresión?', 'Ambas: 50-200 mg/día. En ansiedad se empieza con dosis más bajas (25 mg) por sensibilidad inicial a efectos de activación. Subir gradualmente.', ARRAY['anxiety', 'salud_mental'], TRUE, NULL, now()),
  ('21cc6eaf-c83b-538e-bf90-c731cb1b0b2b', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuál es la diferencia entre obsesión y compulsión?', 'Obsesión: pensamiento/imagen/impulso intrusivo recurrente que genera ansiedad. Compulsión: conducta o acto mental que el paciente realiza para reducir la ansiedad o prevenir un suceso temido.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('b45266e1-a6e6-5e48-89b9-a82cc43c1d7d', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuánto tiempo debe durar una obsesión/compulsión al día para diagnosticar TOC?', 'Más de 1 hora al día, o que cause malestar o deterioro clínicamente significativo.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('fbf06262-9343-53af-b675-3d59c3cfbeda', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuáles son las 4 dimensiones clínicas del TOC?', '1) Contaminación + lavado, 2) Simetría/orden + ''just right'', 3) Daño/responsabilidad + comprobación, 4) Contenido prohibido/tabú + actos mentales.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('086ffa5c-309f-566e-bb26-33080ed94de1', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuál es la dosis de sertralina para TOC vs depresión?', 'TOC: 150–200 mg/día. Depresión: 50–100 mg/día. El TOC requiere el DOBLE de dosis.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('4a0cd628-0e8d-53a6-923b-021267210454', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿En cuánto tiempo se espera respuesta completa al ISRS en TOC?', '10–12 semanas (no 4–6 como en depresión). No cambies de fármaco antes si hay mejoría parcial a las 6 semanas.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('15e8c4cc-8e56-57b3-b959-308eeb05dfc0', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuál es el gold standard psicoterapéutico del TOC?', 'Exposición y Prevención de Respuesta (EPR): exposición gradual al disparador + impedir la compulsión. Equivalente o superior a fármacos aislados.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('2cc12da9-91b6-5e4a-95ba-6481146f1e16', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Qué es PANDAS?', 'Pediatric Autoimmune Neuropsychiatric Disorders Associated with Streptococcus. TOC de inicio SÚBITO en niño post-faringitis estreptocócica. Tratamiento: antibiótico + manejo estándar del TOC.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('b4102ce8-7122-5ee8-a76b-2b6b7592dadc', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Por qué NUNCA se debe autorizar cirugía cosmética en TDC?', 'Empeora el cuadro: el cerebro reinterpreta el nuevo aspecto como otro defecto. Riesgo suicida 4× mayor en TDC — screening de suicidio obligatorio.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('f92b77cb-239d-54a0-ae06-b5c8007d9751', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuál es el tratamiento de 1ª línea en tricotilomanía?', 'Terapia de Reversión de Hábito (TRH). N-acetilcisteína 1200–2400 mg/día tiene buena evidencia. ISRS eficacia limitada.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('1b5a7a1c-d632-5bb3-bd64-56c2eea9ef9a', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Qué antipsicótico se prefiere para augmentar un ISRS en TOC con tics?', 'Aripiprazol 5–15 mg/día. Risperidona 0.5–3 mg sin tics.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('5bd62fa3-c59e-548c-bf72-6d737a5e3dfd', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuánto tiempo se mantiene el tratamiento tras remisión del TOC?', 'Mínimo 1–2 años tras remisión total. El riesgo de recaída es alto al suspender.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('b6397b44-c398-52ec-a8ff-a612a266129f', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuál es la diferencia entre TDC y trastorno delirante somático?', 'En TDC la creencia es sobre la APARIENCIA (defecto físico percibido). En el delirante somático la creencia es sobre ENFERMEDAD, defecto funcional o infestación.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('6bf72b8d-694e-5165-82b3-c1cb3c9f480b', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Por qué se necesitan dosis más ALTAS de ISRS en TOC que en depresión?', 'TOC requiere dosis máximas o cercanas al máximo (ej. fluoxetina 60-80 mg, sertralina 200 mg, fluvoxamina 300 mg) y al menos 10-12 semanas para ver respuesta completa. Depresión: dosis menores y respuesta en 4-6 semanas.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('a0739f27-3b7b-5fae-99fc-c94f882da2b9', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Qué es PANDAS y cuándo se sospecha?', 'Pediatric Autoimmune Neuropsychiatric Disorders Associated with Streptococcal infections. Aparición súbita o exacerbación abrupta de TOC/tics en niño tras infección por estreptococo. Serología positiva confirma.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('3c42cdef-bf26-5127-b9ec-c6262aced6ba', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Qué es la ''exposición con prevención de respuesta'' (EPR) y para qué trastorno es 1ª línea?', 'EPR: exposición gradual al estímulo ansiógeno sin permitir la compulsión. Es la 1ª línea psicoterapéutica para TOC. También útil en TDC (trastorno dismórfico corporal).', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('1ee7aef8-9d84-5f04-96cc-4ac39a73a918', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', 'Mujer 35 años se arranca el pelo de la cabeza y cejas hace 2 años, experimenta alivio. ¿Dx y tx?', 'Tricotilomanía. Tx: habit reversal training (1ª línea) + N-acetilcisteína + ISRS si comorbilidad. Derivado del capítulo TOC y trastornos relacionados.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('e3ebd621-8b80-5133-9cf9-17565adf4402', '19c71fc4-0082-5ad6-bd89-cc4865c6e03e', 'basic', '¿Cuál es la diferencia entre TOC y TOCP (personalidad)?', 'TOC: obsesiones y compulsiones EGO-DISTÓNICAS (el paciente sabe que son absurdas). TOCP: rasgo de personalidad EGO-SINTÓNICO (cree que su perfeccionismo es correcto). Dos entidades distintas en capítulos diferentes.', ARRAY['toc', 'salud_mental'], TRUE, NULL, now()),
  ('40c90c5b-997a-59b5-b507-b7ec73da859d', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuál es la duración mínima de síntomas para diagnosticar TEPT?', '≥1 mes desde el evento traumático. Si es de 3 días a 1 mes, el diagnóstico es trastorno de estrés agudo (TEA).', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('830efae7-b75e-59c3-ab8d-ab710c7fb113', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuáles son los 4 grupos de síntomas del TEPT?', 'B) Intrusión (≥1 de 5) — recuerdos, sueños, flashbacks, malestar ante claves, reacciones fisiológicas. C) Evitación (≥1 de 2). D) Alteraciones negativas de cognición/ánimo (≥2 de 7). E) Hiperactivación (≥2 de 6).', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('6f74927f-d2f5-5b2a-8476-2b5e6977e571', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Qué ISRS tienen aprobación FDA específica para TEPT?', 'Sertralina y paroxetina. Son los únicos con indicación oficial. Venlafaxina XR es alternativa de primera línea.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('e7931325-c84b-5c4d-8111-f69e4bf5a007', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Por qué están contraindicadas las BZD en TEPT?', 'No tratan los síntomas nucleares, interfieren con el procesamiento del trauma en psicoterapia, empeoran la disociación y tienen alto riesgo de dependencia en esta población.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('e987aabb-711c-5078-bc9a-83b6310845e5', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Para qué sirve la prazosina en TEPT y a qué dosis?', 'Reduce pesadillas e hiperactivación nocturna. Antagonista α1-adrenérgico. Iniciar 1 mg nocturno, titular hasta 10 mg.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('3282ff1d-5c81-5b33-92a5-b82afca21336', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Qué es EMDR?', 'Eye Movement Desensitization and Reprocessing. Psicoterapia basada en movimientos oculares bilaterales durante la evocación del recuerdo traumático. Eficacia equivalente a TCC centrada en trauma.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('9a8e44a4-555d-563b-9aba-c15c7779488b', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuál es la diferencia entre trastorno de adaptación y TEPT?', 'El criterio A. TEPT requiere exposición a trauma estricto (muerte/lesión grave/violencia sexual). Adaptación: estresor identificable NO traumático (divorcio, desempleo, mudanza).', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('5cc94f59-72ae-5640-8341-c4f62008cd7c', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuándo aparecen y resuelven los síntomas del trastorno de adaptación?', 'Aparecen dentro de los 3 meses del estresor. Resuelven dentro de los 6 meses tras su cese (salvo que el estresor sea crónico).', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('28d0274e-494d-5565-962f-32c1abdf3009', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuál es la duración mínima para diagnosticar trastorno de duelo prolongado?', '≥12 meses tras la muerte en adultos. ≥6 meses en niños y adolescentes. Nuevo diagnóstico del DSM-5-TR (2022).', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('875a2180-02d6-5d8a-ad44-497bb189d4ef', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿En qué se diferencia el apego reactivo del desinhibido?', 'Ambos por cuidado patogénico. Apego reactivo: niño INHIBIDO, no busca consuelo, no responde emocionalmente. Desinhibido: niño con conductas excesivamente familiares e indiscriminadas con adultos desconocidos.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('b5626727-e6ae-5053-abd3-90c54a97f378', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Qué condiciones debe cumplir una muerte para contar como trauma en el criterio A?', 'Si el paciente se enteró (no presenció), la muerte debe haber sido VIOLENTA O ACCIDENTAL. Una muerte esperada por cáncer, por ejemplo, no cumple criterio A.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('b5a82cf8-05b6-5dd5-9078-fcf3da27bfcc', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuántos síntomas se necesitan para el TEA?', '≥9 síntomas de cualquier categoría (intrusión, ánimo negativo, disociación, evitación, activación), durante 3 días a 1 mes tras el trauma.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('580533ad-3b61-55e3-9db6-d5039241ce30', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuál es la edad de presentación típica del trastorno de apego reactivo?', 'Antes de los 5 años (criterio F). El niño debe tener edad de desarrollo ≥9 meses.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('9379573f-c7c2-52a6-86d1-1f007c7c385e', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Qué especificador del TEPT se aplica si los criterios se cumplen tardíamente?', 'Con expresión retardada: cuando los criterios completos no se cumplen hasta al menos 6 meses tras el evento traumático.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('a3431084-d8c2-5bf9-b73c-05a3fac7fb13', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Cuál es el criterio A del TEPT y por qué es tan específico?', 'Exposición a muerte real o amenaza, lesión grave o violencia sexual, ya sea directa, presenciada, conocida por familiar cercano, o exposición profesional repetida (policía, rescatistas). Otros estresores vitales NO cumplen criterio A — van a trastorno adaptativo.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('753cf2f6-0d00-56dd-96c1-1d56735ad5ed', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Qué diferencia TEA del TEPT en duración?', 'TEA (Trastorno de Estrés Agudo): 3 días - 1 mes tras trauma. TEPT: ≥1 mes. Si persiste más de 1 mes, pasa a TEPT. Ambos requieren criterio A de exposición a trauma severo.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('f336f147-dea5-5e4e-adf1-baaf661bf812', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿En qué paciente con TEPT tiene especial utilidad la prazosina?', 'En TEPT con pesadillas y alteración del sueño. Antagonista α1-adrenérgico. Dosis 1-15 mg nocturnos. También útil en HTA y HBP (mismo mecanismo).', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('910a5ad0-cb5f-500c-a5e7-1286823d265f', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', 'Mujer 70 años con pérdida de su hija hace 18 meses, persiste con anhelo intenso y pensamientos intrusivos diarios sobre ella, con deterioro funcional. ¿Dx?', 'Trastorno de duelo prolongado (DSM-5-TR añadido en 2022). Criterios: ≥12 meses adultos (6 meses niños) con anhelo intenso y ≥3 síntomas adicionales (shock, ira, evitación, etc.) + deterioro.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('115828dc-4b0e-5cb8-b013-56a42f5f4d1b', '7961df40-25bb-59fd-b440-fa3dde5d3181', 'basic', '¿Qué psicoterapias tienen mejor evidencia en TEPT?', 'TCC centrada en trauma, EMDR (desensibilización y reprocesamiento por movimientos oculares), terapia de exposición prolongada. Todas superiores a medicación sola.', ARRAY['trauma', 'salud_mental'], TRUE, NULL, now()),
  ('0de89018-195b-50e7-a980-cfe58990fded', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuál es la diferencia entre TSS e IAD?', 'TSS: síntomas físicos REALES y angustiantes + respuesta psicológica desproporcionada. IAD (hipocondría): preocupación por enfermar con síntomas físicos AUSENTES o LEVES.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('67a15e92-e57d-5291-9472-dda209e40b1d', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué es el signo de Hoover y qué indica?', 'En una ''parálisis'' conversiva de pierna: al pedir al paciente levantar la pierna SANA, se detecta contracción involuntaria (extensión) en la ''parética''. Es un signo POSITIVO de conversión (incompatibilidad con lesión).', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('e5f777a8-3387-5fd2-9324-85d052e60e06', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuál es la diferencia entre trastorno facticio y simulación?', 'Ambos producen síntomas conscientemente. Facticio: motivación INTERNA (asumir rol de enfermo). Simulación: motivación EXTERNA (dinero, licencia, droga, evadir). Simulación no es trastorno mental.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('e6ba3ec8-e8cc-53fd-9117-9f190cd2d421', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué diferencia hay entre conversión, facticio y simulación?', 'Conversión: síntomas INVOLUNTARIOS, el paciente no es consciente de producirlos. Facticio: CONSCIENTE, motivación interna. Simulación: CONSCIENTE, motivación externa clara.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('9a879b7c-d8ae-5e18-85a7-336ec56a021a', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué es el trastorno facticio impuesto a otro?', 'Antes llamado Munchausen por poderes. Un cuidador produce o induce síntomas en un tercero (típicamente hijo). Es una forma de MALTRATO INFANTIL. Requiere protección del menor.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('34553093-2796-5b80-806e-9aaf4e8e5006', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuál es la duración mínima para diagnosticar IAD?', '≥6 meses de preocupación por tener o adquirir una enfermedad grave.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('51585d39-d876-517c-9e96-c036e358a97e', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuáles son los 3 tipos de amnesia disociativa?', 'Localizada (más común: pérdida de un evento o periodo), selectiva (recuerdo parcial del evento) y generalizada (rara, pérdida total de memoria autobiográfica).', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('09c07ebb-00cb-5637-8a21-934722b229dc', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cómo se diferencia amnesia disociativa de amnesia orgánica (Korsakoff, TCE)?', 'Disociativa: sin alteración de conciencia, sin confabulación, información RECUPERABLE con el tiempo. Orgánica: déficit de tiamina (Korsakoff), confabulación, déficits cognitivos asociados.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('1cef95aa-0f48-52ee-9d25-c7007a23a586', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué es la fuga disociativa?', 'Especificador de la amnesia disociativa: viaje o deambulación aparentemente intencionada + amnesia de identidad u otra información autobiográfica. El paciente puede asumir una nueva identidad temporal.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('19a3decc-0d68-5387-a289-a3451464790d', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuál es el criterio clave del trastorno de despersonalización / desrealización?', 'La prueba de realidad permanece INTACTA. El paciente sabe que es una sensación, no una realidad. Es el rasgo que distingue de la psicosis.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('cf8344b3-4228-5d3c-8dfd-f6d39fdfc83f', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuál es el tratamiento base del TID?', 'Psicoterapia trauma-informada en 3 fases: estabilización → procesamiento del trauma → integración. NO hay fármaco con indicación específica. ISRS para depresión/ansiedad, prazosina para pesadillas.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('4377ebf0-bc76-52f1-8098-1879c14eb677', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Por qué se debe evitar BZD en pacientes disociativos?', 'Pueden empeorar la disociación y tienen alto riesgo de dependencia en esta población (alta comorbilidad con TEPT y uso de sustancias).', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('4a4bbdad-ecf5-58a4-aa26-be3879ff59e7', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué porcentaje de adultos sanos ha experimentado despersonalización transitoria?', 'Aproximadamente 50%, especialmente en contextos de fatiga, estrés agudo, alcohol o cannabis. Solo es trastorno cuando es persistente/recurrente y causa malestar o deterioro.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now())
INSERT INTO public.flashcards
  (id, deck_id, card_type, front, back, tags, is_official, user_id, created_at)
VALUES
  ('8b91a5b7-8029-53bd-9d83-4b7b12a84515', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Por qué se renombró ''histeria'' a ''trastorno de conversión''?', 'Porque ''histeria'' era un término estigmatizante y culturalmente cargado. El DSM-5 lo renombró ''síntomas neurológicos funcionales'' y el diagnóstico ahora se basa en signos positivos de incompatibilidad con lesión, no en la búsqueda de conflicto psicológico.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('a35b2dce-ce33-5294-96e8-bb387ca85baa', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', 'Diferencia clave: ¿cómo distinguir TSS de IAD?', 'TSS: hay síntomas físicos REALES (dolor, fatiga, etc.) + preocupación/pensamientos/tiempo excesivos sobre ellos. IAD: preocupación por ENFERMEDAD con síntomas físicos AUSENTES o leves. En ambos: ≥6 meses.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('1ee6fd87-21c7-57f2-b5ef-f5ba046301b5', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', 'En conversión, ¿qué signos indican que es funcional y no orgánico?', 'Incompatibilidad con neuroanatomía: signo de Hoover (debilidad de pierna cede con maniobra contralateral), anestesia en guante/media (no sigue dermatomas), fuerza variable durante exploración. Pruebas complementarias normales.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('7064e511-8011-5d83-867a-7e892b8a9dd7', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué diferencia facticio de simulación?', 'Facticio: motivación INTERNA (ser el enfermo). Simulación: motivación EXTERNA clara (beneficio económico, evadir cárcel/trabajo). Simulación no es trastorno mental, es código V.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('ec703552-26cc-5a65-963c-5b39abcf95de', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Qué alteraciones neurológicas mimica la conversión más frecuentemente?', 'Parálisis no anatómicas, crisis no epilépticas psicógenas (PNES), ceguera funcional, afonía, alteraciones sensitivas. Signos positivos (Hoover, distractibilidad de crisis) confirman.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('9f9c048a-8dec-54e2-ad77-e5b01a6036e5', 'aab1a948-080a-5b97-8afc-bf35d3c9b8f7', 'basic', '¿Cuál es la diferencia clave entre amnesia disociativa y olvido normal o demencia?', 'Disociativa: pérdida súbita de información autobiográfica importante, generalmente de un periodo específico traumático, con función cognitiva intacta. Demencia: pérdida gradual de múltiples dominios cognitivos.', ARRAY['somaticos', 'salud_mental'], TRUE, NULL, now()),
  ('55bef75f-3fac-5a06-8f3e-1d6a1a6d2186', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuál es el TCA con la mortalidad más alta de todos los trastornos psiquiátricos?', 'Anorexia nerviosa. Mortalidad ~5–10% a 10 años. Causa: arritmias, desnutrición y suicidio.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('84755cbe-16c9-5661-a9aa-7198bd7cba91', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuáles son los 2 subtipos de anorexia nerviosa?', 'Restrictivo (sin atracones/purgas en 3 meses) y con atracones/purgas (vómito, laxantes, diuréticos, enemas en 3 meses).', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('2cfb8cb6-daa9-5939-bd33-1f74a49697aa', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué es el signo de Russell y en qué cuadro aparece?', 'Callosidades en el dorso de los nudillos por el contacto repetido con los dientes al inducir el vómito. Aparece en bulimia y en anorexia subtipo con purgas.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('4f1f4591-49c2-5b84-ab1a-baec7693ad34', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuál es la frecuencia mínima de atracones para diagnosticar bulimia?', '≥1 atracón + conducta compensatoria por semana durante al menos 3 meses. Misma frecuencia para trastorno por atracón (sin conducta compensatoria).', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('8ce722d7-30d7-5a6f-a9b3-b6d886315baa', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuál es la dosis de fluoxetina para bulimia nerviosa y por qué es especial?', '60 mg/día. Es el ÚNICO ISRS con aprobación FDA específica para bulimia. Dosis MAYOR que en depresión (20 mg).', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('734b4134-084a-5ad4-ad06-deeebbb031f1', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué fármaco tiene aprobación FDA específica para el trastorno por atracón y a qué dosis?', 'Lisdexanfetamina 50–70 mg/día en adultos. Único aprobado específicamente.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('75d68b71-edf3-54e1-b3b0-dbe7bfd520ae', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Por qué está contraindicado el bupropión en anorexia y bulimia?', 'Reduce el umbral convulsivo. En pacientes con alteraciones electrolíticas por purgas, el riesgo de convulsiones aumenta significativamente.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('414f5194-fba8-5b5f-a370-81b53b521c03', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué es el síndrome de realimentación y cómo se previene?', 'Complicación al iniciar nutrición en paciente muy desnutrido: la insulina desplaza fosfato, potasio y magnesio al intracelular → arritmias, ICC, edema pulmonar. Prevención: tiamina 100–200 mg IV previa, iniciar a 20 kcal/kg/día, suplementar electrolitos, monitoreo diario de electrolitos x 7 días.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('310d48c4-8a11-5b41-abac-17c6a44446b4', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuáles son los umbrales de IMC para la gravedad de la anorexia en adultos?', 'Leve ≥17 · Moderada 16–16.99 · Grave 15–15.99 · Extrema <15 kg/m².', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('7623de6a-2cb7-57bc-bf57-f48205739574', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué diferencia ARFID de anorexia nerviosa?', 'ARFID tiene evitación/restricción alimentaria SIN preocupación por la imagen corporal ni miedo a engordar. Comparte el bajo peso pero no la psicopatología central de la anorexia.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('810f2f2f-ed64-5620-9b6b-a2034138d839', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué diagnóstico se debe sospechar en una persona que come hielo compulsivamente?', 'Pagofagia — fuertemente asociada a anemia ferropénica. Medir ferritina y hemograma. Suele mejorar al corregir el déficit de hierro.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('58e8ec0c-c4ec-5276-8460-e576fe7fea15', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuál es la psicoterapia de primera línea para anorexia nerviosa en adolescentes?', 'Terapia familiar basada en Maudsley (TFB-M). Los padres son los ''agentes del cambio'' al inicio del tratamiento, encargados de la realimentación.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('b4b4e3b1-2180-5fd1-a1c1-fb8e765c4a3d', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué trastornos electrolítico-ácido-base son típicos del vómito autoinducido?', 'Alcalosis metabólica hipoclorémica, con hipocalemia. Pérdida de HCl por el vómito.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('eebd0f68-a8d3-57dc-a58e-3bf58303aefc', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Qué trastorno ácido-base es típico del abuso de laxantes?', 'Acidosis metabólica hiperclorémica (pérdida de bicarbonato intestinal). También hipocalemia por pérdida de K+ en heces.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('fbfc31ee-8bc3-54fb-9357-f472d0f3f71a', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuáles son los dos subtipos de anorexia nerviosa?', 'Restrictivo (pérdida de peso por dieta y ejercicio, sin atracones ni purgas en 3 meses) y con atracones/purgas (episodios recurrentes de atracón o conductas purgativas en 3 meses).', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('07b4e39d-a904-5ca0-9849-f44d723fea4b', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuál es el riesgo médico AGUDO más importante en bulimia con purgas?', 'Hipocalemia por pérdida de K⁺ en vómito → arritmias ventriculares. También alcalosis metabólica hipoclorémica (pérdida de HCl) y deshidratación.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('0036c3cc-7000-5d44-9e14-c963e4ab4ff3', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', 'Adolescente 15 años, IMC 14, amenorrea, bradicardia, restricción alimentaria severa con miedo intenso a engordar. ¿Tx 1ª línea?', 'Terapia Familiar Basada en Maudsley (TFB-M) — 1ª línea en adolescentes con AN. Padres asumen responsabilidad de realimentación. No fármacos como 1ª línea (ISRS no eficaces en cuadro central).', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('e4848081-c012-5585-8a19-a9b9905d1527', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', '¿Cuál es el ÚNICO medicamento con aprobación FDA para bulimia y a qué dosis?', 'Fluoxetina 60 mg/día (dosis mayor que en depresión). Reduce atracones y conductas compensatorias. Siempre junto con TCC.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('60c6f0be-6c46-56a6-a282-930fb88c2fb5', '7031c483-db20-5c86-813d-cecb4531be87', 'basic', 'Paciente con anorexia severa inicia realimentación agresiva → hipofosfatemia, edema, arritmias. ¿Qué es y cómo prevenir?', 'Síndrome de realimentación. Prevención: iniciar con pocas calorías (5-10 kcal/kg/día), suplementar fosfato/potasio/magnesio/tiamina previo, monitoreo electrolitos diario x 7 días. Mortal si no se trata.', ARRAY['tca', 'salud_mental'], TRUE, NULL, now()),
  ('af3972e0-c9c1-5c8f-835b-f04bfd8e6e72', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el tratamiento de primera línea del trastorno de insomnio?', 'Terapia cognitivo-conductual para el insomnio (TCC-I). Superior o equivalente a fármacos a largo plazo. Incluye higiene del sueño, control de estímulos, restricción de sueño y reestructuración cognitiva.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('194fde09-6717-5d80-8a72-b11c1b527bd8', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuáles son los componentes de la tétrada clásica de narcolepsia?', '1) Ataques de sueño, 2) cataplejía (pérdida súbita bilateral del tono muscular desencadenada por emoción), 3) alucinaciones hipnagógicas/hipnopómpicas, 4) parálisis del sueño.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('29929c12-103e-504c-96d4-4d4070d3c455', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el gold standard de tratamiento para la cataplejía en narcolepsia?', 'Oxibato de sodio. Alternativas: pitolisant, venlafaxina, atomoxetina, clomipramina.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('303ed470-9fe8-5890-adc7-3da5edc9250d', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el neurotransmisor deficiente en narcolepsia tipo 1 y la asociación HLA?', 'Deficiencia de orexina (hipocretina) por pérdida autoinmune de neuronas hipotalámicas. Asociación con HLA-DQB1*06:02. Hipocretina en LCR disminuida o indetectable.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('0290d650-e65b-5f3f-a27e-0ffa557cd9bf', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el tratamiento de 1ª línea para la apnea obstructiva del sueño moderada-grave?', 'CPAP nasal. Gold standard. Reduce somnolencia, HTA y eventos cardiovasculares.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('4da590b2-aa73-5381-90fd-38d47eb14b4d', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Por qué se deben evitar BZD y opioides en AOS?', 'Deprimen la ventilación y empeoran las apneas. Son contraindicación relativa.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('c7d7c0b8-5389-5765-9798-dba46fe33237', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Qué parámetro de laboratorio es clave investigar en el síndrome de piernas inquietas?', 'Ferritina. Si es <75 ng/mL, suplementar con hierro oral o IV mejora significativamente el cuadro.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('a9bf6d71-5454-50a6-b24e-4c63c004bd80', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Qué es el fenómeno de aumentación en SPI?', 'Efecto paradójico de los agonistas dopaminérgicos: con el tiempo, el tratamiento empeora el SPI (síntomas aparecen antes, son más intensos, se extienden a otras partes del cuerpo). Por eso gabapentinoides son ahora 1ª línea farmacológica.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('769855a8-d24a-5108-905c-ba0b3cbdb4ef', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿En qué fase del sueño y momento de la noche ocurren las parasomnias NREM?', 'En sueño N3 (ondas lentas), en la PRIMERA mitad de la noche. Ejemplos: sonambulismo y terror nocturno. Hay amnesia del episodio.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('78b80c8c-f099-59bc-8abb-9c82ca976522', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿En qué fase del sueño y momento ocurren las pesadillas?', 'En sueño REM, en la SEGUNDA mitad de la noche. El paciente despierta completamente orientado y recuerda el sueño con detalle.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('f899e208-2d82-5025-8fde-86c22076415b', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cómo diferencias un terror nocturno de una pesadilla?', 'Terror nocturno: N3, 1ª mitad, amnesia, sin relato del sueño. Pesadilla: REM, 2ª mitad, recuerdo vívido del sueño, despertar orientado.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('b1a27ce2-ca56-5857-9a6c-96b74fb26484', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el tratamiento de 1ª línea para pesadillas, especialmente si hay TEPT comórbido?', 'Terapia de ensayo por imágenes (IRT). En TEPT: prazosina 1–10 mg nocturnos, antagonista α1-adrenérgico.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('9e8d6c63-e49c-546a-b77c-1088f83674ce', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Qué enfermedades neurodegenerativas predice el trastorno de conducta del sueño REM (TCSR)?', 'Sinucleinopatías: Parkinson, demencia con cuerpos de Lewy, atrofia multisistémica. ~80% desarrolla una en 10–15 años.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('e1194e21-7914-5a30-bc05-3db0b936c11c', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el tratamiento de 1ª línea del TCSR?', 'Clonazepam 0.25–2 mg nocturno o melatonina 3–12 mg nocturno (preferida en adultos mayores). Seguridad del entorno es clave.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('8283524f-d0bd-5bd9-a043-b82e96e616dd', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el manejo del jet-lag?', 'Melatonina 0.5–3 mg al horario de destino + fototerapia. Ajuste gradual en viajes largos.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('45c8f573-02f8-54ed-abd2-5006c6aa1752', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Qué caracteriza los eventos del sueño REM vs NREM desde el punto de vista clínico?', 'NREM (1ª mitad noche): terrores nocturnos, sonambulismo, sin recuerdo del evento. REM (2ª mitad noche): pesadillas con recuerdo vívido, TCSR (paciente actúa sus sueños).', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('be74ca51-5f0a-5033-a6f5-09604bb236d0', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', 'Varón 65 años patea y grita durante el sueño, su esposa lo denuncia. Recuerda pesadillas violentas. ¿Dx y riesgo a largo plazo?', 'Trastorno de conducta del sueño REM (TCSR). Alto riesgo de enfermedad neurodegenerativa: 80% desarrollará Parkinson o DCL en 10-15 años. Tx: clonazepam o melatonina + seguimiento neurológico.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('7348e124-0155-5e9c-901f-d009c75f4a49', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuál es el tratamiento 1ª línea del síndrome de piernas inquietas y por qué los agonistas dopaminérgicos ya no son la elección principal?', '1ª línea: corregir ferritina (<75 → hierro oral/IV) + gabapentinoides (gabapentina, pregabalina). Agonistas dopaminérgicos (pramipexol, ropinirol) causan ''aumentación'' (empeoramiento paradójico), por eso están relegados.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('3d8b6c13-2974-5a9e-83db-713ee20e492f', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Cuáles son los componentes de la tétrada clásica de narcolepsia?', '1) Somnolencia diurna excesiva, 2) cataplejía (pérdida súbita del tono con emoción), 3) alucinaciones hipnagógicas/hipnopómpicas, 4) parálisis del sueño. Deficiencia de orexina/hipocretina.', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('4b72f7dd-bb8b-5b24-a413-78226fec4660', '1061175e-a84c-583f-ae9e-f5b4f6e5b6cd', 'basic', '¿Por qué los BZD NO son de elección en insomnio crónico?', 'Tolerancia, dependencia, deterioro cognitivo, caídas en adultos mayores, insomnio de rebote al suspender. 1ª línea: TCC para insomnio (TCC-I). Si fármaco, preferir antagonistas de orexina (suvorexant) o agonistas melatonina (ramelteón).', ARRAY['sueno', 'salud_mental'], TRUE, NULL, now()),
  ('203a0611-f9f5-5224-99eb-09351b71a62b', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuáles son los 3 clusters de trastornos de personalidad?', 'A (raros/excéntricos): paranoide, esquizoide, esquizotípica. B (dramáticos/emocionales): antisocial, límite, histriónica, narcisista. C (ansiosos/temerosos): evitativa, dependiente, obsesivo-compulsiva.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('d8f0f2c5-3b4e-53b3-8083-4f181a5769bb', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuál es el tratamiento de primera línea para el trastorno límite de personalidad?', 'DBT (terapia dialéctica conductual) de Marsha Linehan. Incluye: mindfulness, regulación emocional, tolerancia al malestar y efectividad interpersonal.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('ec2a71c4-b14c-54ea-8e94-1af1881deca9', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuál es la diferencia entre TOCP y TOC?', 'TOCP: rasgo de personalidad EGO-SINTÓNICO (la persona cree que su perfeccionismo es correcto y bueno). TOC: obsesiones y compulsiones EGO-DISTÓNICAS (la persona sabe que son absurdas y quiere librarse).', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('dc6ce842-0969-5573-8fcf-f9e349244e8e', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué antecedente es necesario para diagnosticar trastorno antisocial de personalidad?', 'Evidencia de trastorno de la conducta antes de los 15 años. Sin este antecedente, no puede diagnosticarse. Además, el paciente debe tener ≥18 años.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('91de5f05-0f35-5742-8b3c-6a96c05a7bcc', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cómo se diferencia el trastorno esquizoide del esquizotípico?', 'Esquizoide: desapego e indiferencia, prefiere la soledad. Esquizotípica: además, tiene distorsiones cognitivas/perceptivas y excentricidad (pensamiento mágico, ideas de referencia).', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now())
INSERT INTO public.flashcards
  (id, deck_id, card_type, front, back, tags, is_official, user_id, created_at)
VALUES
  ('ef27aaa3-da82-53c4-bef2-ba3ae8d6048e', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cómo se diferencia el trastorno evitativo del esquizoide?', 'Evitativa: DESEA relaciones pero las evita por miedo al rechazo. Esquizoide: NO DESEA relaciones, prefiere estar solo.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('ff2035a9-aeda-5364-b040-de89f5c0ea09', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué es la ''escisión'' en el TLP?', 'Mecanismo defensivo nuclear del TLP: alternancia entre idealización (''eres perfecto'') y devaluación (''eres horrible'') del mismo objeto. Genera relaciones interpersonales inestables e intensas.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('7df3bba7-1c40-5fe0-b013-cb578753f0cc', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuáles son los 9 criterios del TLP (DSM-5)?', '1) Esfuerzos por evitar abandono, 2) relaciones inestables con escisión, 3) alteración de identidad, 4) impulsividad en ≥2 áreas, 5) conductas suicidas/autolesivas, 6) inestabilidad afectiva, 7) vacío crónico, 8) ira intensa, 9) ideación paranoide o disociación transitorias. Se requieren ≥5 de 9.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('40c2f847-c747-5141-9429-7804a243fa9c', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuál es la tasa de suicidio consumado en el TLP?', 'Aproximadamente 10%. Alto riesgo — el screening suicida y el manejo de crisis son claves.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('595ff3aa-b679-5e1d-8fcf-2cc2361380cb', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué porcentaje de pacientes con TLP tiene antecedentes de trauma infantil?', 'Aproximadamente 70%. Abuso sexual, físico o negligencia. No es ''causa única'' pero es factor de riesgo central.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('d6bee4f4-2c11-522c-9f4b-b0587b5e2117', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué fármacos se pueden usar sintomáticamente en TLP?', 'Estabilizadores (lamotrigina, valproato) para inestabilidad afectiva e impulsividad. Antipsicóticos atípicos bajos (aripiprazol, quetiapina) para ideación paranoide y agresividad. ISRS para depresión comórbida. EVITAR BZD (desinhibición + adicción).', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('3656a8f7-50e0-5e57-b7f0-22ee905b8bef', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuál es el núcleo del trastorno narcisista de personalidad?', 'Grandiosidad + necesidad de admiración + falta de empatía. Sentido de privilegio, explotación interpersonal, arrogancia.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('e2624de1-9de5-50cc-acce-bd5220d3c6f0', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué caracteriza al trastorno histriónico de personalidad?', 'Emotividad excesiva y búsqueda de atención. Necesita ser el centro. Comportamiento seductor, expresión emocional superficial y cambiante, sugestionabilidad.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('869de93b-f7ae-57d9-bdb8-2265a59a97c9', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué caracteriza al trastorno dependiente de personalidad?', 'Necesidad excesiva de ser cuidado, conducta sumisa y pegadiza, miedo a la separación. Dificultad para tomar decisiones sin tranquilización, dificultad para estar solo, busca urgentemente una nueva relación cuando una termina.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('6cefc4c2-2ffb-56eb-ba2e-87bc1cc91df2', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Por qué un cambio súbito de personalidad en un adulto debe alertar sobre causa orgánica?', 'Los trastornos de personalidad inician en adolescencia o adultez temprana y son estables. Un cambio abrupto en adulto sugiere causa orgánica: tumor frontal, demencia, infección del SNC, enfermedad médica o sustancia.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('71e57c05-9d2c-5bb5-aa66-aac93caa2ec3', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cuál es el tratamiento 1ª línea para TLP y por qué se diseñó específicamente para este trastorno?', 'Terapia Dialéctico-Conductual (DBT) de Marsha Linehan. Combina mindfulness + tolerancia al malestar + regulación emocional + efectividad interpersonal. Diseñada específicamente para TLP por la inestabilidad emocional intensa.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('f088b6ac-9122-52a0-bd14-b5a533d158e2', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', 'Paciente 28 años con patrón de relaciones intensas e inestables (idealización/devaluación), autolesiones, sensación crónica de vacío, miedo al abandono. ¿Dx?', 'Trastorno límite de personalidad (TLP). Requiere ≥5 de 9 criterios, inicio en adultez temprana, patrón persistente y pervasivo. Alta comorbilidad con TEPT, TCA, sustancias.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('55f28605-bf22-5c9c-a021-bf42618ff1e1', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Cómo diferenciar personalidad esquizoide de esquizotípica?', 'Esquizoide: desapego social, frialdad emocional, prefiere estar solo, sin distorsiones cognitivas. Esquizotípica: además, EXCENTRICIDAD + ideas de referencia + pensamiento mágico + ansiedad social. Esquizotípica está en el espectro esquizofrénico.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('9c171b25-5cc5-5ea1-bd09-0af53b649e93', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿Qué rasgos distinguen la personalidad antisocial de un criminal común?', 'Antisocial requiere: ≥18 años, evidencia de trastorno de conducta antes de 15 años, patrón pervasivo de violación de derechos, SIN remordimiento, impulsividad, engaño. Un criminal que planea por beneficio económico no necesariamente tiene antisocial.', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('2923dfa4-06bb-54c1-add0-86549cab59ee', '3f0c92fe-1e66-5f70-82f6-ab0c4c5835eb', 'basic', '¿En qué cluster están los trastornos ''ansiosos o temerosos'' y cuáles son?', 'Cluster C: Evitativa (desea vínculo pero miedo rechazo), Dependiente (necesita que la cuiden), Obsesivo-compulsiva de personalidad (TOCP, perfeccionismo rígido).', ARRAY['personalidad', 'salud_mental'], TRUE, NULL, now()),
  ('bf199348-f0f5-5b49-a9bb-3d2eec3878c9', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué antecedente se necesita para diagnosticar trastorno antisocial en un adulto?', 'Evidencia de trastorno de la conducta antes de los 15 años. Sin este antecedente, no se diagnostica antisocial en ≥18 años.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('c53ed57e-71f8-50d4-adaa-855ec99784c5', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cuáles son las 4 categorías de síntomas del trastorno de la conducta?', '1) Agresión a personas/animales, 2) destrucción de propiedad, 3) engaño o robo, 4) violaciones graves de normas. Se requieren ≥3 síntomas en últimos 12 meses, ≥1 en últimos 6.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('dc2e6ba4-e1b7-5726-bc1a-a3fb4ad2cb3a', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cómo se diferencia el trastorno negativista desafiante del trastorno de la conducta?', 'Negativista: enfado, desafío, vengatividad — sin violación grave de derechos. Conducta: agresión, destrucción, robo, violaciones graves de normas sociales.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('0f720364-9e79-56bb-bf84-d37091f45ded', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cuáles son los dos patrones (A1 y A2) del trastorno explosivo intermitente?', 'A1: Arrebatos de baja intensidad (verbales o físicos sin daño) ≥2 veces/semana × ≥3 meses. A2: Arrebatos de alta intensidad (daño a propiedad o lesión física) ≥3 en últimos 12 meses. Basta uno.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('a5dd4cfc-9d60-5caf-96d6-c16e715831f3', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cuáles son los criterios de piromanía?', 'A) Incendios deliberados ≥1 ocasión. B) Tensión previa. C) Fascinación/atracción por el fuego. D) Placer al prenderlo o presenciarlo. E) NO por motivación económica/vengativa/ideológica/ocultar delito/respuesta a delirio. F) No explicado por CC, manía o antisocial.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('a46d253a-ba2f-54ba-bfe0-6c6948a7fdb3', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué caracteriza a la cleptomanía?', 'Impulso recurrente de robar objetos que NO son necesarios para uso personal ni por valor económico. Tensión previa + placer/alivio al robar. No es por rabia, venganza, delirios. ~3:1 mujeres.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('95a1790b-a46c-572b-8c2d-c94d27ebc3dd', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cuál es el tratamiento de 1ª línea del trastorno negativista desafiante?', 'Parent Management Training (PMT) — terapia conductual con los padres, que aprenden reforzamiento positivo, consecuencias consistentes y manejo de límites. Terapia familiar. Tratar comorbilidades (TDAH muy frecuente).', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('27171b81-8dc8-5f9b-aa9b-3f2f888217ee', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué fármacos tienen evidencia en trastorno explosivo intermitente?', 'ISRS (fluoxetina con mejor evidencia). Estabilizadores del ánimo (valproato, litio). Antipsicóticos atípicos en casos graves. TCC con manejo de ira es 1ª línea.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('86562a03-6d29-5d4e-9b76-e2117c62c31f', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué es el especificador ''con emociones prosociales limitadas'' (callous-unemotional)?', 'Especificador del trastorno de la conducta: rasgos de falta de remordimiento, poca empatía, afecto superficial, despreocupación por el rendimiento. Predice peor pronóstico y mayor riesgo de antisocial adulto.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('a73447b8-37ff-59d1-96f9-aaa01c051841', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Por qué un robo motivado por necesidad económica no es cleptomanía?', 'La cleptomanía requiere que los objetos robados NO sean necesarios ni tengan valor económico para el paciente. Si hay motivación económica, es robo común (no trastorno mental).', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('c10acddd-5917-5770-9d2d-245d8987733d', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué fármacos pueden ayudar en cleptomanía?', 'ISRS (fluoxetina) y naltrexona (antagonista opioide que modula sistema de recompensa). Ambos con evidencia moderada. TCC con desensibilización encubierta es 1ª línea.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('e9581e68-dded-5cbc-978c-525e717c9cdb', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cuál es la comorbilidad más frecuente del trastorno negativista desafiante?', 'TDAH (alrededor del 40%). Tratar el TDAH con estimulantes frecuentemente mejora también el negativismo.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('f4409532-db53-561e-a554-32534b94e385', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué antecedente es OBLIGATORIO para diagnosticar trastorno antisocial de personalidad?', 'Evidencia de trastorno de la conducta antes de los 15 años. Sin ese antecedente, aunque el paciente tenga conducta antisocial adulta, NO se diagnostica como personalidad antisocial.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('e3a50e41-2e18-5efc-8247-5a43e31e14a5', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Cuáles son las 4 categorías de síntomas del trastorno de la conducta?', '1) Agresión a personas/animales, 2) destrucción de propiedad, 3) engaño o robo, 4) violaciones graves de normas. Se requieren ≥3 síntomas en 12 meses, con ≥1 en los últimos 6.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('169f3d41-c827-5fe6-b2d4-5d4b36e76aaf', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', 'Niño 7 años con rabietas explosivas, irritabilidad crónica, desafío a autoridad. ¿Cómo diferenciar negativista desafiante de TDDD?', 'Negativista: desafío e ira. TDDD (Trastorno de Desregulación Disruptiva del Ánimo): rabietas severas ≥3/sem + irritabilidad crónica entre rabietas. TDDD se creó para NO sobrediagnosticar bipolar pediátrico.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('0f7e63bb-878c-5214-af10-26c48f191aff', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', '¿Qué diferencia piromanía de un pirómano por otros motivos?', 'Piromanía: incendios deliberados + fascinación por el fuego + alivio/placer al prenderlo, SIN motivación instrumental (dinero, venganza, ocultar otro delito). Si hay motivación externa, NO es piromanía.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('da9d185e-ace4-5d19-a117-6ac7dcc00fe2', 'debb4556-a5f6-5529-96b0-20e8ad36b9a1', 'basic', 'Mujer 30 años con episodios de robo de objetos que NO necesita, alivio tras el acto, sin ganancia económica. ¿Dx y tx?', 'Cleptomanía. Tx: ISRS + naltrexona + TCC. Impulso recurrente de robar objetos sin utilidad ni valor monetario, con sensación de tensión que se alivia al robar.', ARRAY['impulsos', 'salud_mental'], TRUE, NULL, now()),
  ('67d10eec-1ead-55ed-aa05-94abee334d1d', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuál es la duración mínima de síntomas para diagnosticar un episodio depresivo mayor?', 'Dos semanas con ≥5 de 9 síntomas, al menos uno siendo ánimo depresivo o anhedonia.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('2f6c7d14-e1f5-5ddd-9cca-5ded52754ce2', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Qué significa la nemotecnia SIGECAPS?', 'Los 9 síntomas del TDM: Sleep (sueño), Interest (interés/anhedonia), Guilt (culpa), Energy (energía), Concentration (concentración), Appetite (apetito), Psychomotor (psicomotor), Suicide (ideación suicida), más el ánimo bajo como ancla.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('44d5ac7a-4be0-57c9-b341-c477303cc843', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuál es el tratamiento de 1ª línea farmacológico del TDM?', 'ISRS (sertralina, escitalopram, fluoxetina) + psicoterapia (TCC o TIP). Si falla: optimizar dosis, cambiar a otro ISRS/IRSN o atípico, aumentar (litio, T3, antipsicótico atípico).', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('f3a94a6f-2ca4-589c-bc27-f0805258aadc', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuánto tarda un ISRS en hacer efecto?', 'Respuesta inicial en 2–4 semanas, efecto completo en 6–8 semanas. No cambiar antes de 4–6 semanas.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('ace35888-9897-5169-a8e7-7e2c1a3f487b', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuánto debe durar el tratamiento antidepresivo tras la remisión?', 'Primer episodio: 6–9 meses tras remisión. Dos o más episodios o episodio grave/psicótico: 2 años o indefinido.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('a9d32983-0aa1-5208-ad39-173566613541', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuál es la duración mínima del trastorno depresivo persistente (distimia)?', '≥2 años en adultos, ≥1 año en niños/adolescentes (donde puede presentarse como irritabilidad). No más de 2 meses sin síntomas durante ese periodo.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('23f26b58-b053-5dde-9d6d-b902b3459836', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Qué es la ''depresión doble''?', 'Paciente con distimia crónica que además desarrolla episodios depresivos mayores superpuestos. Peor pronóstico.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('3ade6f70-6d3e-5aa3-b13b-5b39a5447bc7', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuáles son los 4 síntomas afectivos nucleares del TDPM?', '1) Labilidad afectiva marcada, 2) irritabilidad o conflictos interpersonales, 3) ánimo deprimido/desesperanza, 4) ansiedad/tensión. Se requiere ≥1 de estos + totales ≥5 síntomas.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('949bd871-1b7b-5c01-8399-bf8752ff09f7', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cómo se confirma el diagnóstico de TDPM?', 'Con registro diario PROSPECTIVO durante ≥2 ciclos sintomáticos. Los síntomas deben mejorar tras el inicio del sangrado y estar ausentes/mínimos en la semana posmenstrual.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('51739c0f-3eb4-5684-b435-b60076c0087a', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuál es la edad mínima y máxima para diagnosticar TDDD?', 'Mínimo 6 años, máximo 18 años. Inicio de síntomas antes de los 10 años es criterio obligatorio.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('69aee653-9151-502e-a941-64a01c186213', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Por qué se creó el diagnóstico de TDDD?', 'Para reducir el sobre-diagnóstico de trastorno bipolar pediátrico. Niños con irritabilidad crónica sin episodios maníacos discretos entran aquí, no en bipolar, evitando uso inapropiado de estabilizadores del ánimo.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('f1c2dbde-64af-52dd-b4e1-2654af0fdaf2', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuándo está indicada la TEC en depresión?', 'Riesgo suicida agudo, depresión psicótica, catatonia, embarazo (1er trimestre especialmente), refractaria a múltiples fármacos, rechazo alimentario severo.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('1581b5f5-1eeb-5127-a1d6-46e0c1a73fe1', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Qué ISRS se prefiere en embarazo y cuál evitar?', 'Preferir sertralina. EVITAR paroxetina (asociada a defectos cardíacos).', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('39bc2ff9-fc06-5d16-b2f8-ae97337b0a37', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Qué fármaco tiene efecto rápido en depresión con suicidalidad aguda?', 'Ketamina IV o esketamina intranasal (efecto en horas-días). Alternativa urgente junto con TEC.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('8e17ef2e-8884-5d0f-8ba1-7aa3599f4497', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿En qué pacientes NO debe usarse bupropión?', 'Antecedente de convulsiones, TCA activo con purgas (↓ umbral convulsivo), abstinencia aguda de alcohol o BZD. También no es ideal para ansiedad marcada.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('f9bb8822-f94f-5261-87ae-579c3ad69f07', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Qué es la nemotecnia SIGECAPS y qué debe incluir obligatoriamente un episodio depresivo mayor?', 'SIGECAPS: Sueño, Interés (anhedonia), Guilt (culpa), Energía, Concentración, Apetito, Psicomotor, Suicidio. ≥5 de 9 síntomas × ≥2 semanas, con al menos UNO siendo ánimo deprimido O anhedonia.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('13cc8473-6806-584d-9239-098613c142df', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuánto tiempo debe mantenerse un antidepresivo tras el primer episodio depresivo mayor?', '6-9 meses tras la remisión completa para prevenir recaída. Si es ≥2 episodios o episodio severo/psicótico, considerar mantenimiento ≥2 años o indefinido.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('f1431103-af9a-5395-a02a-6915ca27fc66', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', 'Mujer 32 años con síntomas premenstruales severos de ira, ansiedad y depresión los 7 días antes de menstruar, que desaparecen tras el sangrado. ¿Dx y criterio clave?', 'Trastorno Disfórico Premenstrual (TDPM). Criterio clave: confirmación prospectiva en ≥2 ciclos sintomáticos (no basta retrospectivo). Tx: ISRS (continuo o solo fase luteal), ACO combinado.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now())
INSERT INTO public.flashcards
  (id, deck_id, card_type, front, back, tags, is_official, user_id, created_at)
VALUES
  ('81a2727a-aec5-5300-8554-9677e19307f5', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Cuándo está indicada la TEC (terapia electroconvulsiva) en depresión?', 'Depresión psicótica, catatonia, refractaria a múltiples fármacos, riesgo suicida agudo, embarazo con depresión severa, rechazo alimentario. NO es ''último recurso'' — en estas condiciones es 1ª línea por respuesta rápida.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now()),
  ('34ba3f96-7458-5df4-b6de-8862119324b8', 'd6a7a64c-08e2-53f6-83c1-d52b14c7e3a2', 'basic', '¿Qué fármaco tiene efecto rápido (horas-días) en depresión refractaria y suicidalidad aguda?', 'Ketamina IV o esketamina intranasal. Actúa sobre receptores NMDA. Efecto en horas, útil como puente mientras otros tratamientos hacen efecto. Alternativa a TEC cuando se requiere respuesta rápida.', ARRAY['depresivos', 'salud_mental'], TRUE, NULL, now())
